31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    /**
59	     * Syntactic email validation: a non-empty local part, a single '@', and a
60	     * domain with at least one dot-separated label ending in a letter-only TLD.
61	     */
62	    private static final Pattern EMAIL_PATTERN =
63	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    /**
84	     * Normalise a raw telephone number to E.164 form.
85	     *
86	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
87	     * code are kept when present; otherwise country code '+61' is assumed and a
88	     * single leading '0' is dropped from the national digits. The result must have
89	     * between 8 and 15 digits after the '+'.
90	     *
91	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
92	     */
93	    static String toE164(String raw) {
94	        if (raw == null) {
95	            return null;
96	        }
97	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
98	        String digits;
99	        if (cleaned.startsWith("+")) {
100	            digits = cleaned.substring(1);
101	        } else {
102	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
103	            digits = "61" + national;
104	        }
105	        if (!digits.matches("[0-9]{8,15}")) {
106	            return null;
107	        }
108	        return "+" + digits;
109	    }
110	
111	    /**
112	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
113	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
114	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
115	     * input normalises to the empty string.
116	     */
117	    private static String normaliseIdentity(String value) {
118	        if (value == null) {
119	            return "";
120	        }
121	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
122	    }
123	
124	    /**
125	     * Build the customer code for a new owner as {@code '<LAST3>-<NNNN>'}, where LAST3 is the
126	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
127	     * sequence equal to one more than the current number of owners.
128	     */
129	    private String nextCustomerCode(String lastName) {
130	        String letters = lastName == null ? "" : lastName;
131	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase();
132	        int sequence = this.clinicService.findAllOwners().size() + 1;
133	        return String.format("%s-%04d", last3, sequence);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
139	        Collection<Owner> owners;
140	        if (lastName != null) {
141	            owners = this.clinicService.findOwnerByLastName(lastName);
142	        } else {
143	            owners = this.clinicService.findAllOwners();
144	        }
145	        if (owners.isEmpty()) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
164	        String telephone = toE164(ownerFieldsDto.getTelephone());
165	        if (telephone == null) {
166	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
167	        }
168	        String email = ownerFieldsDto.getEmail();
169	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
170	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	        }
172	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
173	            .map(Owner::getTelephone)
174	            .map(OwnerRestControllerV1::toE164)
175	            .filter(existing -> existing != null)
176	            .anyMatch(telephone::equals);
177	        if (telephoneInUse) {
178	            return new ResponseEntity<>(HttpStatus.CONFLICT);
179	        }
180	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
181	        if (!sharesHousehold) {
182	            String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
183	            String addressKey = normaliseIdentity(ownerFieldsDto.getAddress());
184	            boolean householdInUse = this.clinicService.findAllOwners().stream()
185	                .anyMatch(existing ->
186	                    normaliseIdentity(existing.getLastName()).equals(lastNameKey)
187	                        && normaliseIdentity(existing.getAddress()).equals(addressKey));
188	            if (householdInUse) {
189	                return new ResponseEntity<>(HttpStatus.CONFLICT);
190	            }
191	        }
192	        HttpHeaders headers = new HttpHeaders();
193	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
194	        owner.setTelephone(telephone);
195	        owner.setEmail(email == null ? null : email.toLowerCase());
196	        if (owner.getRegistrationDate() == null) {
197	            owner.setRegistrationDate(LocalDate.now());
198	        }
199	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
200	        this.clinicService.saveOwner(owner);
201	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
202	        headers.setLocation(UriComponentsBuilder.newInstance()
203	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
204	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
210	        String telephone = toE164(ownerFieldsDto.getTelephone());
211	        if (telephone == null) {
212	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
213	        }
214	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
215	        if (currentOwner == null) {
216	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
217	        }
218	        String email = ownerFieldsDto.getEmail();
219	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
220	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
221	        }
222	        currentOwner.setAddress(ownerFieldsDto.getAddress());
223	        currentOwner.setCity(ownerFieldsDto.getCity());
224	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
225	        currentOwner.setLastName(ownerFieldsDto.getLastName());
226	        currentOwner.setTelephone(telephone);
227	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
228	        this.clinicService.saveOwner(currentOwner);
229	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
230	    }
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
